/* Operation Empower B1.2: Partner Academy. Charcoal and black surfaces, metallic gold accents, silver secondary text.
   Muted text uses #939cac (>= 5:1 on every surface here), not the admin --t3 (#667085), which fails WCAG AA for body text. */
.academy{--ac-bg:#0f1012;--ac-s1:#17181b;--ac-s2:#1f2125;--ac-s3:#2a2d31;--ac-t1:#f1f5f9;--ac-t2:#cfc7bc;--ac-muted:#939cac;--ac-gold:#d1b266;--ac-gold-deep:#a8873f;--ac-line:rgba(207,199,188,.18);--ac-ok:#34d399;--ac-warn:#fbbf24;
  min-height:100dvh;background:var(--ac-bg);color:var(--ac-t1);font-family:var(--font-dm);font-size:16px;line-height:1.6}
.academy *{box-sizing:border-box}
.academy a{color:var(--ac-gold)}
/* Links in running text are underlined, not distinguished by colour alone (WCAG 1.4.1). */
.academy p a,.academy li a,.ac-prose a{text-decoration:underline;text-underline-offset:2px}
.academy :focus-visible{outline:3px solid rgba(209,178,102,.75);outline-offset:2px;border-radius:4px}
.ac-skip{position:absolute;left:-9999px;top:8px;background:var(--ac-gold);color:#131416;padding:8px 12px;border-radius:6px;font-weight:700}
.ac-skip:focus{left:16px;z-index:10}
.ac-header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 16px;border-bottom:1px solid var(--ac-line);background:linear-gradient(180deg,#131416,#0f1012)}
.ac-brand{display:flex;align-items:center;gap:10px;color:var(--ac-t1)!important;text-decoration:none;font-family:var(--font-syne);letter-spacing:.06em;font-size:14px}
.ac-brand small{display:block;font-family:var(--font-dm);color:var(--ac-muted);letter-spacing:.14em;font-size:11px}
.ac-header nav{display:flex;flex-wrap:wrap;gap:6px}
.ac-header nav a{color:var(--ac-t2);text-decoration:none;padding:8px 10px;border-radius:8px;font-size:14px}
.ac-header nav a[aria-current="page"],.ac-header nav a:hover{color:var(--ac-t1);background:var(--ac-s2)}
3:.academy{--ac-bg:#0f1012;--ac-s1:#17181b;--ac-s2:#1f2125;--ac-s3:#2a2d31;--ac-t1:#f1f5f9;--ac-t2:#cfc7bc;--ac-muted:#939cac;--ac-gold:#d1b266;--ac-gold-deep:#a8873f;--ac-line:rgba(207,199,188,.18);--ac-ok:#34d399;--ac-warn:#fbbf24;
5:.academy *{box-sizing:border-box}
6:.academy a{color:var(--ac-gold)}
8:.academy p a,.academy li a,.ac-prose a{text-decoration:underline;text-underline-offset:2px}
9:.academy :focus-visible{outline:3px solid rgba(209,178,102,.75);outline-offset:2px;border-radius:4px}

